do $guard$ begin if not exists (select 1 from public.seminar_student_projects where project_slug='arbelaez-defensive-cyber-definition' and project_title='Defensive Cybersecurity Project — Define the Asset & Defense' and sprints='[{"n":1,"gate":"El entorno local funciona y la condición de prueba es reproducible.","goal":"Elige el caso que corresponde al proyecto y documenta activo, amenaza y criterio de éxito. Descarga el laboratorio, lee README.md y revisa docker-compose.yml para identificar puertos y servicios. Inicia el entorno y conserva configuración y línea base.","tests":["Verifica que los servicios arrancan y una petición legítima funciona.","Registra código HTTP, latencia, fecha y condición de prueba; elimina secretos de las evidencias."],"title":"1 · Alcance y línea base","theory":["Activo, amenaza, control y evidencia forman un modelo de defensa. Define éxito para peticiones legítimas y para el escenario de abuso.","Trabaja con el laboratorio local provisto. Los casos disponibles son resiliencia HTTP, abuso de autenticación, control de acceso y XSS almacenado."],"workshop":["Elige el caso que corresponde al proyecto y documenta activo, amenaza y criterio de éxito.","Descarga el laboratorio, lee README.md y revisa docker-compose.yml para identificar puertos y servicios.","Inicia el entorno y conserva configuración y línea base."],"deliverable":"Diagrama del entorno, alcance autorizado, configuración y registro de línea base.","theory_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cyber#stage-1","workshop_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cyber#stage-1"},{"n":2,"gate":"La evidencia distingue el caso de abuso de una petición legítima y permite reproducirlo.","goal":"Sigue el caso correspondiente de la biblioteca, usando exclusivamente el entorno local. Inspecciona la petición, HTML, código del servicio y logs para localizar el control ausente. Fija entrada, duración y condiciones; registra una ejecución previa a la defensa.","tests":["Comprueba que el caso produce el comportamiento descrito y que puedes repetirlo.","Añade una prueba legítima de control con la misma configuración."],"title":"2 · Reproducir y explicar el caso","theory":["Un hallazgo debe enlazar entrada, comportamiento observado y causa. Un error aislado no demuestra una vulnerabilidad.","Para resiliencia, mide también disponibilidad del tráfico legítimo; para autorización, prueba acceso permitido y denegado."],"workshop":["Sigue el caso correspondiente de la biblioteca, usando exclusivamente el entorno local.","Inspecciona la petición, HTML, código del servicio y logs para localizar el control ausente.","Fija entrada, duración y condiciones; registra una ejecución previa a la defensa."],"deliverable":"Petición o fixture, logs saneados, resultado previo y explicación de la causa.","theory_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cyber#stage-2","workshop_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cyber#stage-2"},{"n":3,"gate":"La defensa controla el caso y las pruebas legítimas siguen pasando.","goal":"Implementa el control del caso elegido y documenta el archivo y la decisión técnica. Reinicia o reconstruye los servicios afectados siguiendo el README. Repite exactamente el escenario anterior y una petición legítima.","tests":["Compara los mismos indicadores antes y después.","Prueba un caso límite y comprueba que no se bloquea el usuario legítimo."],"title":"3 · Implementar la defensa","theory":["El control se aplica en la capa que decide: límites en proxy/servicio, autorización por recurso, validación de entrada y salida segura según el caso.","La defensa debe reducir el abuso conservando el comportamiento legítimo. Cambia una condición a la vez para atribuir el resultado."],"workshop":["Implementa el control del caso elegido y documenta el archivo y la decisión técnica.","Reinicia o reconstruye los servicios afectados siguiendo el README.","Repite exactamente el escenario anterior y una petición legítima."],"deliverable":"Diff/commit, configuración y tabla antes/después con las mismas condiciones.","theory_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cyber#stage-3","workshop_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cyber#stage-3"},{"n":4,"gate":"El docente puede reproducir los resultados; los límites y las pruebas pendientes están explícitos.","goal":"Crea una matriz de pruebas con esperado/obtenido y referencia a evidencia. Reproduce un fallo de la defensa, corrige y vuelve a probar. Entrega README para reconstruir el laboratorio, commits, reporte de causa/control y limitaciones.","tests":["Arranca desde una configuración limpia y repite la matriz.","Demuestra en vivo el caso antes/después y explica qué protege y qué queda fuera del alcance."],"title":"4 · Regresión y defensa técnica","theory":["Una defensa se evalúa por resultados y límites, no por instalar una herramienta. Los logs sustentan cada conclusión.","La regresión incluye permitido, bloqueado, límite, reinicio y errores de configuración."],"workshop":["Crea una matriz de pruebas con esperado/obtenido y referencia a evidencia.","Reproduce un fallo de la defensa, corrige y vuelve a probar.","Entrega README para reconstruir el laboratorio, commits, reporte de causa/control y limitaciones."],"deliverable":"Matriz, logs, corrección verificable y demostración técnica.","theory_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cyber#stage-4","workshop_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cyber#stage-4"}]'::jsonb and project_mode='guided_definition') then raise exception 'project_changed_since_inspection'; end if; end $guard$;
update public.seminar_student_projects set project_title='Access Defense Lab — Validación y control de acceso local',project_summary='Laboratorio defensivo local de inicio de sesión con dos roles, validación de entradas y registro de accesos permitidos y rechazados.',objective='Demostrar en localhost que un visitante o lector no puede ejecutar acciones de administrador y que los eventos no exponen secretos.',stack=array['Python or Web','input validation','logging','access control','threat modeling','safe sandbox']::text[],sprints='[{"n":1,"title":"Contrato y alcance","goal":"Definir actores, operaciones, datos sintéticos y criterios de aceptación.","deliverable":"Contrato, backlog y cinco casos verificables.","theory":"Definir actores, operaciones, datos sintéticos y criterios de aceptación.","workshop":"Definir actores, operaciones, datos sintéticos y criterios de aceptación. Guarda código, condición de prueba y resultados esperado/observado."},{"n":2,"title":"Modelo y permisos","goal":"Diseñar entidades, relaciones y matriz de acceso antes de programar.","deliverable":"Diagrama de datos/UML y matriz actor–acción.","theory":"Diseñar entidades, relaciones y matriz de acceso antes de programar.","workshop":"Diseñar entidades, relaciones y matriz de acceso antes de programar. Guarda código, condición de prueba y resultados esperado/observado."},{"n":3,"title":"Base ejecutable","goal":"Preparar entorno, repositorio y primera operación de extremo a extremo.","deliverable":"Código ejecutable y primer registro o salida verificable.","theory":"Preparar entorno, repositorio y primera operación de extremo a extremo.","workshop":"Preparar entorno, repositorio y primera operación de extremo a extremo. Guarda código, condición de prueba y resultados esperado/observado."},{"n":4,"title":"Función principal","goal":"Construir el flujo principal con responsabilidades separadas.","deliverable":"Demostración reproducible del flujo principal.","theory":"Construir el flujo principal con responsabilidades separadas.","workshop":"Construir el flujo principal con responsabilidades separadas. Guarda código, condición de prueba y resultados esperado/observado."},{"n":5,"title":"Persistencia y validación","goal":"Guardar estado, validar entradas y probar fallos y límites.","deliverable":"Datos persistentes y evidencia de casos inválidos.","theory":"Guardar estado, validar entradas y probar fallos y límites.","workshop":"Guardar estado, validar entradas y probar fallos y límites. Guarda código, condición de prueba y resultados esperado/observado."},{"n":6,"title":"Función de la especialidad","goal":"Implementar la operación específica del dominio asignado.","deliverable":"Función de dominio y prueba de su criterio de éxito.","theory":"Implementar la operación específica del dominio asignado.","workshop":"Implementar la operación específica del dominio asignado. Guarda código, condición de prueba y resultados esperado/observado."},{"n":7,"title":"Pruebas y corrección","goal":"Ejecutar pruebas de permiso, límite, estado vacío y regresión.","deliverable":"Matriz esperado/observado y defecto corregido.","theory":"Ejecutar pruebas de permiso, límite, estado vacío y regresión.","workshop":"Ejecutar pruebas de permiso, límite, estado vacío y regresión. Guarda código, condición de prueba y resultados esperado/observado."},{"n":8,"title":"Entrega y defensa","goal":"Ejecutar desde un entorno limpio y explicar decisiones y limitaciones.","deliverable":"Repositorio, instrucciones, evidencia y defensa en vivo.","theory":"Ejecutar desde un entorno limpio y explicar decisiones y limitaciones.","workshop":"Ejecutar desde un entorno limpio y explicar decisiones y limitaciones. Guarda código, condición de prueba y resultados esperado/observado."}]'::jsonb,content_sections='[{"kicker":"PROYECTO DEFINIDO · 2026-10-14","title":"Producto concreto y criterio de entrega","body":"Laboratorio defensivo local de inicio de sesión con dos roles, validación de entradas y registro de accesos permitidos y rechazados.","items":["Demostrar en localhost que un visitante o lector no puede ejecutar acciones de administrador y que los eventos no exponen secretos.","Construir en la especialidad actual; no convertir este proyecto en una página web.","Usar datos o entradas de prueba explícitos y documentar su procedencia.","El plan define la entrega; los avances se registran solo cuando existe evidencia.","Definición docente: no representa una elección ni una aprobación realizada por el estudiante."]},{"body":"El MVP debe demostrar un control de seguridad y producir evidencia observable.","items":["Un escenario local/sintético reproducible.","Control defensivo: validación, rate limiting, autenticación endurecida o detección basada en reglas.","Registro de eventos sin secretos.","Pruebas de caso permitido y caso bloqueado/alertado."],"title":"2. Producto mínimo funcional defensivo","kicker":"MVP"},{"body":"Cada control debe estar conectado con una amenaza y con una forma de medir si funcionó.","items":["Crea tabla Amenaza → Control → Evidencia.","Dibuja arquitectura y puntos donde se valida/registra.","Usa datos sintéticos o entradas propias para las pruebas.","Mantén límites, umbrales y reglas en configuración cuando sea posible."],"title":"3. Diseña la evidencia antes de programar","kicker":"BUILD"},{"body":"Las pruebas deben validar robustez sin crear capacidad ofensiva contra terceros.","items":["Caso válido y caso inválido/malformado.","Caso exactamente en el límite del control.","Caso repetido para comprobar logging y rate/threshold.","Logs sin contraseñas, tokens o información sensible.","Confirmación de que el entorno no acepta objetivos externos."],"title":"4. Pruebas obligatorias","kicker":"QA / SAFETY"},{"body":"Debes poder explicar la relación entre riesgo, implementación y resultado.","items":["Declaración de alcance autorizado.","Threat model sencillo y arquitectura.","Código del control defensivo.","Evidencia antes/después o permitido/bloqueado.","Matriz de pruebas y limitaciones conocidas."],"title":"5. Evidencia para la defensa final","kicker":"EVIDENCE"}]'::jsonb,project_mode='fixed',teacher_note=' | Definición docente 2026-10-14; mantiene especialidad, identidad y progreso. No confirma decisiones del estudiante.',initial_project_title='Access Defense Lab — Validación y control de acceso local',initial_project_summary='Laboratorio defensivo local de inicio de sesión con dos roles, validación de entradas y registro de accesos permitidos y rechazados.',initial_objective='Demostrar en localhost que un visitante o lector no puede ejecutar acciones de administrador y que los eventos no exponen secretos.',initial_stack=array['Python or Web','input validation','logging','access control','threat modeling','safe sandbox']::text[], updated_at=now() where project_slug='arbelaez-defensive-cyber-definition';
do $guard$ begin if not exists (select 1 from public.seminar_student_projects where project_slug='chavarriaga-3d-print-definition' and project_title='3D Printing Project — Define a Functional Object' and sprints='[{"n":1,"gate":"El objeto tiene función definida y el modelo inicial cambia mediante parámetros.","goal":"Define usuario, función, carga de uso y restricciones de espacio. Mide el objeto que debe encajar. Crea una tabla de parámetros en milímetros: ancho, alto, espesor y holgura. En Fusion, crea un boceto restringido y extruye el volumen inicial.","tests":["Verifica unidades y cotas contra las mediciones.","Cambia el ancho y comprueba que el modelo se regenera sin errores."],"title":"1 · Necesidad, medidas y primer modelo","theory":["CAD paramétrico representa intención mediante cotas, restricciones y operaciones. El boceto debe definir una función y sus dimensiones críticas.","Un soporte de escritorio es un ejemplo inicial; el producto individual se confirma antes de construir."],"workshop":["Define usuario, función, carga de uso y restricciones de espacio. Mide el objeto que debe encajar.","Crea una tabla de parámetros en milímetros: ancho, alto, espesor y holgura.","En Fusion, crea un boceto restringido y extruye el volumen inicial."],"deliverable":"Croquis acotado, tabla de parámetros, captura del boceto y archivo nativo.","theory_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cad#stage-1","workshop_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cad#stage-1"},{"n":2,"gate":"Las variantes se regeneran y cumplen función y dimensiones del contrato.","goal":"Añade los elementos funcionales: alojamiento, apoyo, orificios o nervaduras según el contrato. Nombra parámetros y operaciones. Evita cotas duplicadas o geometría sin restricción. Documenta tres variantes cambiando parámetros.","tests":["Revisa interferencias, espesores y acceso a los elementos de montaje.","Regenera las tres variantes y verifica las dimensiones críticas."],"title":"2 · Geometría funcional y diseño reutilizable","theory":["El historial de operaciones explica cómo se construye la pieza. Las restricciones deben conservar relaciones al cambiar medidas.","Holgura y espesor se eligen para el material y proceso reales; no hay un valor universal válido para todas las impresoras."],"workshop":["Añade los elementos funcionales: alojamiento, apoyo, orificios o nervaduras según el contrato.","Nombra parámetros y operaciones. Evita cotas duplicadas o geometría sin restricción.","Documenta tres variantes cambiando parámetros."],"deliverable":"Archivo editable, historial de operaciones y comparación de variantes.","theory_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cad#stage-2","workshop_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cad#stage-2"},{"n":3,"gate":"El archivo es fabricable y la prueba de ajuste justifica la configuración. Sin impresora, registra fabricación pendiente.","goal":"Exporta la pieza e impórtala en el laminador de la impresora disponible. Confirma escala en mm, orientación y perfil de máquina/material. Inspecciona la vista por capas. Imprime primero una probeta de ajuste si hay encajes; registra parámetros y después fabrica la pieza.","tests":["Comprueba dimensiones en el laminador y ausencia de capas o paredes inesperadas.","Compara el encaje de la probeta con la holgura prevista antes de imprimir la pieza completa."],"title":"3 · Preparación y fabricación","theory":["El archivo nativo conserva la intención; STL o 3MF representa la geometría para fabricación. El laminador transforma esa geometría en trayectorias.","Orientación, soportes, altura de capa y material afectan ajuste, resistencia y tiempo. Los valores se documentan para la máquina elegida."],"workshop":["Exporta la pieza e impórtala en el laminador de la impresora disponible.","Confirma escala en mm, orientación y perfil de máquina/material. Inspecciona la vista por capas.","Imprime primero una probeta de ajuste si hay encajes; registra parámetros y después fabrica la pieza."],"deliverable":"Modelo nativo, STL/3MF, capturas de capas y ficha de fabricación.","theory_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cad#stage-3","workshop_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cad#stage-3"},{"n":4,"gate":"El producto cumple los criterios medidos; la fabricación pendiente se declara como pendiente, no aprobada.","goal":"Mide dimensiones críticas con el instrumento disponible y registra resolución. Prueba la función con el objeto real. Identifica un defecto y ajusta el modelo. Entrega versiones antes/después, plano, archivos nativo y de fabricación e instrucciones de uso.","tests":["Compara medida nominal y real; calcula desviación y verifica la tolerancia acordada.","Repite el ensayo funcional después del cambio. Si solo hay simulación, identifica qué falta validar físicamente."],"title":"4 · Medición, iteración y defensa","theory":["La validación compara medidas y función del producto físico con el contrato. Una imagen de render no demuestra fabricación.","La iteración modifica un parámetro por una razón medible y conserva las versiones."],"workshop":["Mide dimensiones críticas con el instrumento disponible y registra resolución.","Prueba la función con el objeto real. Identifica un defecto y ajusta el modelo.","Entrega versiones antes/después, plano, archivos nativo y de fabricación e instrucciones de uso."],"deliverable":"Tabla de medidas, fotos, prueba funcional, iteración y defensa del historial.","theory_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cad#stage-4","workshop_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cad#stage-4"}]'::jsonb and project_mode='guided_definition') then raise exception 'project_changed_since_inspection'; end if; end $guard$;
update public.seminar_student_projects set project_title='DeskStand — Soporte paramétrico para dispositivo',project_summary='Soporte de escritorio ajustable a medidas de un dispositivo de prueba, con ancho, ángulo y espesor como parámetros.',object…13587 tokens truncated…eñar entidades, relaciones y matriz de acceso antes de programar.","deliverable":"Diagrama de datos/UML y matriz actor–acción.","theory":"Diseñar entidades, relaciones y matriz de acceso antes de programar.","workshop":"Diseñar entidades, relaciones y matriz de acceso antes de programar. Guarda código, condición de prueba y resultados esperado/observado."},{"n":3,"title":"Base ejecutable","goal":"Preparar entorno, repositorio y primera operación de extremo a extremo.","deliverable":"Código ejecutable y primer registro o salida verificable.","theory":"Preparar entorno, repositorio y primera operación de extremo a extremo.","workshop":"Preparar entorno, repositorio y primera operación de extremo a extremo. Guarda código, condición de prueba y resultados esperado/observado."},{"n":4,"title":"Función principal","goal":"Construir el flujo principal con responsabilidades separadas.","deliverable":"Demostración reproducible del flujo principal.","theory":"Construir el flujo principal con responsabilidades separadas.","workshop":"Construir el flujo principal con responsabilidades separadas. Guarda código, condición de prueba y resultados esperado/observado."},{"n":5,"title":"Persistencia y validación","goal":"Guardar estado, validar entradas y probar fallos y límites.","deliverable":"Datos persistentes y evidencia de casos inválidos.","theory":"Guardar estado, validar entradas y probar fallos y límites.","workshop":"Guardar estado, validar entradas y probar fallos y límites. Guarda código, condición de prueba y resultados esperado/observado."},{"n":6,"title":"Función de la especialidad","goal":"Implementar la operación específica del dominio asignado.","deliverable":"Función de dominio y prueba de su criterio de éxito.","theory":"Implementar la operación específica del dominio asignado.","workshop":"Implementar la operación específica del dominio asignado. Guarda código, condición de prueba y resultados esperado/observado."},{"n":7,"title":"Pruebas y corrección","goal":"Ejecutar pruebas de permiso, límite, estado vacío y regresión.","deliverable":"Matriz esperado/observado y defecto corregido.","theory":"Ejecutar pruebas de permiso, límite, estado vacío y regresión.","workshop":"Ejecutar pruebas de permiso, límite, estado vacío y regresión. Guarda código, condición de prueba y resultados esperado/observado."},{"n":8,"title":"Entrega y defensa","goal":"Ejecutar desde un entorno limpio y explicar decisiones y limitaciones.","deliverable":"Repositorio, instrucciones, evidencia y defensa en vivo.","theory":"Ejecutar desde un entorno limpio y explicar decisiones y limitaciones.","workshop":"Ejecutar desde un entorno limpio y explicar decisiones y limitaciones. Guarda código, condición de prueba y resultados esperado/observado."}]'::jsonb,content_sections='[{"kicker":"PROYECTO DEFINIDO · 2026-10-14","title":"Producto concreto y criterio de entrega","body":"Análisis reproducible de registros deportivos sintéticos: sesión, minutos de práctica, aciertos y dificultad.","items":["Comparar rendimiento por dificultad y práctica, detectar datos inválidos y comunicar resultados sin afirmar causalidad.","Construir en la especialidad actual; no convertir este proyecto en una página web.","Usar datos o entradas de prueba explícitos y documentar su procedencia.","El plan define la entrega; los avances se registran solo cuando existe evidencia.","Definición docente: no representa una elección ni una aprobación realizada por el estudiante."]},{"body":"El MVP es un análisis reproducible de principio a fin.","items":["Carga del dataset desde una ruta o fuente documentada.","Diccionario de datos.","Limpieza justificada de tipos, faltantes, duplicados e inconsistencias.","Estadística descriptiva pertinente.","Al menos tres visualizaciones que ayuden a responder la pregunta.","Conclusión y limitaciones."],"title":"2. Producto mínimo funcional de analista","kicker":"MVP"},{"body":"Cada bloque de código debe tener una razón y cada gráfica una interpretación.","items":["Importación y validación inicial.","Limpieza en pasos reproducibles, evitando editar datos manualmente.","EDA: distribución, grupos y relaciones relevantes.","Visualizaciones con títulos, unidades y etiquetas.","Modelo o ML solo si aporta algo que el análisis descriptivo no resuelve."],"title":"3. Estructura tu notebook como una investigación","kicker":"BUILD"},{"body":"Un resultado que no puede reproducirse o que interpreta mal los datos no es un resultado válido.","items":["Reinicia el entorno y ejecuta todo desde cero.","Verifica tipos, unidades y valores faltantes después de limpiar.","Evita escalas/gráficas que distorsionen la comparación.","Distingue correlación de causalidad.","Comprueba que cada conclusión tenga una tabla, estadística o gráfica que la respalde."],"title":"4. Control de calidad del análisis","kicker":"QA"},{"body":"Tu presentación debe contar una historia de datos completa y verificable.","items":["Pregunta y fuente del dataset.","Notebook reproducible y diccionario de datos.","Evidencia antes/después de la limpieza.","Tres o más visualizaciones justificadas.","Hallazgos, limitaciones y una operación en vivo sobre los datos."],"title":"5. Evidencia para la defensa final","kicker":"EVIDENCE"}]'::jsonb,project_mode='fixed',teacher_note=' | Definición docente 2026-10-14; mantiene especialidad, identidad y progreso. No confirma decisiones del estudiante.',initial_project_title='Sports Data Lab — Rendimiento y consistencia',initial_project_summary='Análisis reproducible de registros deportivos sintéticos: sesión, minutos de práctica, aciertos y dificultad.',initial_objective='Comparar rendimiento por dificultad y práctica, detectar datos inválidos y comunicar resultados sin afirmar causalidad.',initial_stack=array['Python','Google Colab or Jupyter','Pandas','NumPy','Matplotlib','optional scikit-learn']::text[], updated_at=now() where project_slug='mazo-data-analyst-definition';
do $guard$ begin if not exists (select 1 from public.seminar_student_projects where project_slug='rincon-data-analyst-definition' and project_title='Python / Data Analyst Project — Define Your Question & Dataset' and sprints='[{"n":1,"goal":"Choose a real analytical question, dataset source, variables and success criteria.","title":"Question + dataset definition","deliverable":"Project charter + dataset link/source"},{"n":2,"goal":"Load the dataset reproducibly and understand columns, units, types and scope.","title":"Import + data dictionary","deliverable":"Notebook + data dictionary"},{"n":3,"goal":"Handle types, missing values, duplicates and obvious inconsistencies with documented decisions.","title":"Data cleaning","deliverable":"Clean dataset pipeline + before/after evidence"},{"n":4,"goal":"Compute relevant descriptive statistics and explore distributions/relationships.","title":"Descriptive analysis","deliverable":"EDA notebook section + findings"},{"n":5,"goal":"Build clear plots that directly answer parts of the analytical question.","title":"Visualization","deliverable":"At least 3 justified visualizations"},{"n":6,"goal":"Add grouping, correlation, hypothesis-style comparisons or a simple ML model only if justified.","title":"Deeper analysis / optional model","deliverable":"Analysis extension + interpretation"},{"n":7,"goal":"Organize the notebook/report, rerun from a clean state and verify every result.","title":"Data story + reproducibility QA","deliverable":"Reproducible final notebook/dashboard draft"},{"n":8,"goal":"Present the question, evidence, findings, limitations and one live code/data operation.","title":"Analyst defense","deliverable":"Final notebook/dashboard + short presentation"}]'::jsonb and project_mode='guided_definition') then raise exception 'project_changed_since_inspection'; end if; end $guard$;
update public.seminar_student_projects set project_title='Gaming Data Lab — Catálogo y tendencias',project_summary='Análisis de un catálogo sintético de videojuegos con género, año, plataforma y puntuación.',objective='Construir un notebook que valide registros, compare distribuciones y comunique tendencias sin generalizar datos simulados al mercado real.',stack=array['Python','Google Colab or Jupyter','Pandas','NumPy','Matplotlib','optional scikit-learn']::text[],sprints='[{"n":1,"title":"Contrato y alcance","goal":"Definir actores, operaciones, datos sintéticos y criterios de aceptación.","deliverable":"Contrato, backlog y cinco casos verificables.","theory":"Definir actores, operaciones, datos sintéticos y criterios de aceptación.","workshop":"Definir actores, operaciones, datos sintéticos y criterios de aceptación. Guarda código, condición de prueba y resultados esperado/observado."},{"n":2,"title":"Modelo y permisos","goal":"Diseñar entidades, relaciones y matriz de acceso antes de programar.","deliverable":"Diagrama de datos/UML y matriz actor–acción.","theory":"Diseñar entidades, relaciones y matriz de acceso antes de programar.","workshop":"Diseñar entidades, relaciones y matriz de acceso antes de programar. Guarda código, condición de prueba y resultados esperado/observado."},{"n":3,"title":"Base ejecutable","goal":"Preparar entorno, repositorio y primera operación de extremo a extremo.","deliverable":"Código ejecutable y primer registro o salida verificable.","theory":"Preparar entorno, repositorio y primera operación de extremo a extremo.","workshop":"Preparar entorno, repositorio y primera operación de extremo a extremo. Guarda código, condición de prueba y resultados esperado/observado."},{"n":4,"title":"Función principal","goal":"Construir el flujo principal con responsabilidades separadas.","deliverable":"Demostración reproducible del flujo principal.","theory":"Construir el flujo principal con responsabilidades separadas.","workshop":"Construir el flujo principal con responsabilidades separadas. Guarda código, condición de prueba y resultados esperado/observado."},{"n":5,"title":"Persistencia y validación","goal":"Guardar estado, validar entradas y probar fallos y límites.","deliverable":"Datos persistentes y evidencia de casos inválidos.","theory":"Guardar estado, validar entradas y probar fallos y límites.","workshop":"Guardar estado, validar entradas y probar fallos y límites. Guarda código, condición de prueba y resultados esperado/observado."},{"n":6,"title":"Función de la especialidad","goal":"Implementar la operación específica del dominio asignado.","deliverable":"Función de dominio y prueba de su criterio de éxito.","theory":"Implementar la operación específica del dominio asignado.","workshop":"Implementar la operación específica del dominio asignado. Guarda código, condición de prueba y resultados esperado/observado."},{"n":7,"title":"Pruebas y corrección","goal":"Ejecutar pruebas de permiso, límite, estado vacío y regresión.","deliverable":"Matriz esperado/observado y defecto corregido.","theory":"Ejecutar pruebas de permiso, límite, estado vacío y regresión.","workshop":"Ejecutar pruebas de permiso, límite, estado vacío y regresión. Guarda código, condición de prueba y resultados esperado/observado."},{"n":8,"title":"Entrega y defensa","goal":"Ejecutar desde un entorno limpio y explicar decisiones y limitaciones.","deliverable":"Repositorio, instrucciones, evidencia y defensa en vivo.","theory":"Ejecutar desde un entorno limpio y explicar decisiones y limitaciones.","workshop":"Ejecutar desde un entorno limpio y explicar decisiones y limitaciones. Guarda código, condición de prueba y resultados esperado/observado."}]'::jsonb,content_sections='[{"kicker":"PROYECTO DEFINIDO · 2026-10-14","title":"Producto concreto y criterio de entrega","body":"Análisis de un catálogo sintético de videojuegos con género, año, plataforma y puntuación.","items":["Construir un notebook que valide registros, compare distribuciones y comunique tendencias sin generalizar datos simulados al mercado real.","Construir en la especialidad actual; no convertir este proyecto en una página web.","Usar datos o entradas de prueba explícitos y documentar su procedencia.","El plan define la entrega; los avances se registran solo cuando existe evidencia.","Definición docente: no representa una elección ni una aprobación realizada por el estudiante."]},{"body":"El MVP es un análisis reproducible de principio a fin.","items":["Carga del dataset desde una ruta o fuente documentada.","Diccionario de datos.","Limpieza justificada de tipos, faltantes, duplicados e inconsistencias.","Estadística descriptiva pertinente.","Al menos tres visualizaciones que ayuden a responder la pregunta.","Conclusión y limitaciones."],"title":"2. Producto mínimo funcional de analista","kicker":"MVP"},{"body":"Cada bloque de código debe tener una razón y cada gráfica una interpretación.","items":["Importación y validación inicial.","Limpieza en pasos reproducibles, evitando editar datos manualmente.","EDA: distribución, grupos y relaciones relevantes.","Visualizaciones con títulos, unidades y etiquetas.","Modelo o ML solo si aporta algo que el análisis descriptivo no resuelve."],"title":"3. Estructura tu notebook como una investigación","kicker":"BUILD"},{"body":"Un resultado que no puede reproducirse o que interpreta mal los datos no es un resultado válido.","items":["Reinicia el entorno y ejecuta todo desde cero.","Verifica tipos, unidades y valores faltantes después de limpiar.","Evita escalas/gráficas que distorsionen la comparación.","Distingue correlación de causalidad.","Comprueba que cada conclusión tenga una tabla, estadística o gráfica que la respalde."],"title":"4. Control de calidad del análisis","kicker":"QA"},{"body":"Tu presentación debe contar una historia de datos completa y verificable.","items":["Pregunta y fuente del dataset.","Notebook reproducible y diccionario de datos.","Evidencia antes/después de la limpieza.","Tres o más visualizaciones justificadas.","Hallazgos, limitaciones y una operación en vivo sobre los datos."],"title":"5. Evidencia para la defensa final","kicker":"EVIDENCE"}]'::jsonb,project_mode='fixed',teacher_note='Trabajo colaborativo verificado con Tomás González Giraldo. Existe sesión compartida de Seminario registrada el 2026-09-16. Mantener seguimiento conjunto del proyecto con evidencia individual por estudiante. | Definición docente 2026-10-14; mantiene especialidad, identidad y progreso. No confirma decisiones del estudiante.',initial_project_title='Gaming Data Lab — Catálogo y tendencias',initial_project_summary='Análisis de un catálogo sintético de videojuegos con género, año, plataforma y puntuación.',initial_objective='Construir un notebook que valide registros, compare distribuciones y comunique tendencias sin generalizar datos simulados al mercado real.',initial_stack=array['Python','Google Colab or Jupyter','Pandas','NumPy','Matplotlib','optional scikit-learn']::text[], updated_at=now() where project_slug='rincon-data-analyst-definition';
