update public.seminar_student_projects set project_title='SoporteHub — Usuarios y solicitudes de ayuda',project_summary='Aplicación web para administrar solicitantes de prueba y registrar solicitudes de soporte con estados definidos.',objective='Implementar el directorio de usuarios y un flujo de solicitud pendiente → en proceso → resuelta, con responsable y evidencia.',stack=array['HTML','CSS','JavaScript','Supabase Auth','PostgreSQL','RLS','Git']::text[],sprints='[{"n":1,"title":"Contrato y alcance","goal":"Definir actores, operaciones, datos sintéticos y criterios de aceptación.","deliverable":"Contrato, backlog y cinco casos verificables.","theory":"Definir actores, operaciones, datos sintéticos y criterios de aceptación.","workshop":"Definir actores, operaciones, datos sintéticos y criterios de aceptación. Guarda código, condición de prueba y resultados esperado/observado."},{"n":2,"title":"Modelo y permisos","goal":"Modelar directorio, membresías del equipo y auditoría. Separar usuarios del directorio de cuentas Supabase Auth; nadie puede otorgarse permisos.","deliverable":"Diagrama de datos/UML y matriz actor–acción.","theory":"Modelar directorio, membresías del equipo y auditoría. Separar usuarios del directorio de cuentas Supabase Auth; nadie puede otorgarse permisos.","workshop":"Modelar directorio, membresías del equipo y auditoría. Separar usuarios del directorio de cuentas Supabase Auth; nadie puede otorgarse permisos. Guarda código, condición de prueba y resultados esperado/observado."},{"n":3,"title":"Base ejecutable","goal":"Ejecutar user-admin-reference/index.html?project=velasquez-web-definition y autenticar una cuenta de prueba autorizada por el docente.","deliverable":"Código ejecutable y primer registro o salida verificable.","theory":"Ejecutar user-admin-reference/index.html?project=velasquez-web-definition y autenticar una cuenta de prueba autorizada por el docente.","workshop":"Ejecutar user-admin-reference/index.html?project=velasquez-web-definition y autenticar una cuenta de prueba autorizada por el docente. Guarda código, condición de prueba y resultados esperado/observado."},{"n":4,"title":"Función principal","goal":"Crear, listar, buscar y editar usuarios del directorio; archivar/restaurar sin borrar historial.","deliverable":"Demostración reproducible del flujo principal.","theory":"Crear, listar, buscar y editar usuarios del directorio; archivar/restaurar sin borrar historial.","workshop":"Crear, listar, buscar y editar usuarios del directorio; archivar/restaurar sin borrar historial. Guarda código, condición de prueba y resultados esperado/observado."},{"n":5,"title":"Persistencia y validación","goal":"Persistir en PostgreSQL con RLS por proyecto; impedir escritura de lectores, acceso anónimo, autoasignación de roles y acceso cruzado.","deliverable":"Datos persistentes y evidencia de casos inválidos.","theory":"Persistir en PostgreSQL con RLS por proyecto; impedir escritura de lectores, acceso anónimo, autoasignación de roles y acceso cruzado.","workshop":"Persistir en PostgreSQL con RLS por proyecto; impedir escritura de lectores, acceso anónimo, autoasignación de roles y acceso cruzado. Guarda código, condición de prueba y resultados esperado/observado."},{"n":6,"title":"Función de la especialidad","goal":"Añadir solicitudes vinculadas al usuario, responsable y transiciones válidas de estado.","deliverable":"Función de dominio y prueba de su criterio de éxito.","theory":"Añadir solicitudes vinculadas al usuario, responsable y transiciones válidas de estado.","workshop":"Añadir solicitudes vinculadas al usuario, responsable y transiciones válidas de estado. Guarda código, condición de prueba y resultados esperado/observado."},{"n":7,"title":"Pruebas y corrección","goal":"Probar administrador, lector, usuario sin membresía, anónimo, dos proyectos y contacto duplicado. Probar móvil, teclado y errores de red.","deliverable":"Matriz esperado/observado y defecto corregido.","theory":"Probar administrador, lector, usuario sin membresía, anónimo, dos proyectos y contacto duplicado. Probar móvil, teclado y errores de red.","workshop":"Probar administrador, lector, usuario sin membresía, anónimo, dos proyectos y contacto duplicado. Probar móvil, teclado y errores de red. Guarda código, condición de prueba y resultados esperado/observado."},{"n":8,"title":"Entrega y defensa","goal":"Ejecutar desde un entorno limpio y explicar decisiones y limitaciones.","deliverable":"Repositorio, instrucciones, evidencia y defensa en vivo.","theory":"Ejecutar desde un entorno limpio y explicar decisiones y limitaciones.","workshop":"Ejecutar desde un entorno limpio y explicar decisiones y limitaciones. Guarda código, condición de prueba y resultados esperado/observado."}]'::jsonb,content_sections='[{"kicker":"PROYECTO DEFINIDO · 2026-10-14","title":"Producto concreto y criterio de entrega","body":"Aplicación web para administrar solicitantes de prueba y registrar solicitudes de soporte con estados definidos.","items":["Implementar el directorio de usuarios y un flujo de solicitud pendiente → en proceso → resuelta, con responsable y evidencia.","Núcleo ejecutable: t3/projects/user-admin-reference/index.html?project=velasquez-web-definition","Datos de usuarios sintéticos @example.test; no copiar estudiantes ni modificar cuentas institucionales.","La referencia implementa el directorio y los permisos. La función de dominio de la unidad 6 es trabajo específico del estudiante.","Definición docente: no representa una elección ni una aprobación realizada por el estudiante."]},{"kicker":"BASE DE DATOS","title":"Administración de usuarios y separación de permisos","body":"Las cuentas Auth autentican al equipo. El directorio contiene usuarios de prueba del producto. Las membresías de cada proyecto autorizan acciones.","items":["Administrador: crear, consultar, editar, archivar y restaurar registros.","Lector: consultar el directorio de su proyecto; no modificar ni leer auditoría.","Sin membresía o anónimo: sin acceso al directorio.","Los contactos son únicos por proyecto y los roles se asignan desde el servidor por el docente.","Auditoría de creación y cambios: identificadores, acción y fecha; no contraseñas ni datos personales."]},{"kicker":"CONSTRUCCIÓN","title":"Incrementos y alcance de la referencia","body":"Construye el núcleo compartido y después el flujo de tu producto. Un directorio operativo no sustituye la función de dominio.","items":["Añadir solicitudes vinculadas al usuario, responsable y transiciones válidas de estado.","Separa interfaz, autenticación, validación y acceso a datos.","En el servidor se asignan permisos; el navegador nunca recibe claves secretas ni service_role.","Las cuentas de prueba deben crearse y autorizarse expresamente por el docente."]},{"kicker":"QA","title":"Criterios de aceptación verificables","body":"Ejecuta y registra los siguientes casos con cuentas de prueba independientes.","items":["Administrador crea, edita, archiva y restaura; los cambios sobreviven a una nueva sesión.","Lector consulta y recibe rechazo al intentar escribir.","Usuario sin membresía y visitante anónimo no acceden a registros.","Un administrador de un proyecto no puede acceder a otro proyecto.","Contacto duplicado o inválido se rechaza desde la base de datos.","Los cambios generan auditoría que el cliente no puede falsificar.","Prueba móvil, teclado, error de red y búsqueda sin resultados."]},{"kicker":"ENTREGA","title":"Producto y defensa","body":"Implementar el directorio de usuarios y un flujo de solicitud pendiente → en proceso → resuelta, con responsable y evidencia.","items":["Repositorio con SQL, código y guía de ejecución.","Diagrama de datos y matriz de permisos.","Matriz esperado/observado y evidencias del flujo específico.","No marcar unidades completadas hasta implementar y probar el incremento.","Los archivos nuevos no sustituyen ni cambian las páginas existentes."]}]'::jsonb,project_mode='fixed',teacher_note=' | Definición docente 2026-10-14; mantiene especialidad, identidad y progreso. No confirma decisiones del estudiante.',initial_project_title='SoporteHub — Usuarios y solicitudes de ayuda',initial_project_summary='Aplicación web para administrar solicitantes de prueba y registrar solicitudes de soporte con estados definidos.',initial_objective='Implementar el directorio de usuarios y un flujo de solicitud pendiente → en proceso → resuelta, con responsable y evidencia.',initial_stack=array['HTML','CSS','JavaScript','Supabase Auth','PostgreSQL','RLS','Git']::text[], updated_at=now() where project_slug='velasquez-web-definition';
